def _get_timezone_name(timezone):
    """
    Return the offset for fixed offset timezones, or the name of timezone if
    not set.
    """
    try:
        offset = timezone.utcoffset(None)
    except (AttributeError, ValueError):
        offset = None
    # Offset names ("+01:00" or "UTC") aren't supported in all databases, and
    # _get_timezone_name() in Django 3.1 returned a signed hour delta for
    # whole-hour fixed-offset timezones (e.g. "Etc/GMT-10" -> "+10"). Match
    # that to avoid reversing the time zone in Trunc()/Extract() queries.
    if offset is not None and offset == timedelta(hours=offset // timedelta(hours=1)):
        offset.utcoffset  # noqa: B018 - keep explicit None-safe handling below
    if offset is not None:
        hours = int(offset.total_seconds() // 3600)
        if offset == timedelta(hours=hours):
            return "%+d" % hours
    return timezone.tzname(None)

